import React, { useState } from 'react';

function Login({ onLogin, message }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loginType, setLoginType] = useState('user'); // ✅ for user/admin dropdown

  const handleSubmit = (e) => {
    e.preventDefault();
    onLogin(username, password, loginType);
  };

  return (
    <div
      className="relative min-h-screen flex flex-col bg-cover bg-center"
      style={{
        backgroundImage: "url('/medical.jpg')",
      }}
    >
      {/* Dark overlay */}
      <div className="absolute inset-0 bg-black/50"></div>

      {/* ✅ Navigation Bar */}
      <nav className="relative z-20 flex justify-between items-center px-8 py-4 bg-white/10 backdrop-blur-lg border-b border-white/20 shadow-md">
        <h1 className="text-white text-2xl font-bold tracking-wide">💊 MediShop</h1>
        <div className="space-x-6">
          <button
            className="text-white hover:text-indigo-300 font-medium transition"
            onClick={() => window.location.reload()}
          >
            Login
          </button>
          <button
            className="text-white hover:text-indigo-300 font-medium transition"
            onClick={() => alert('Register form coming soon!')}
          >
            Register
          </button>
        </div>
      </nav>

      {/* ✅ Login Section */}
      <div className="relative z-10 flex-grow flex items-center justify-center p-4">
        <div className="bg-white/20 backdrop-blur-lg p-8 rounded-xl shadow-2xl w-full max-w-md border border-white/30">
          <h2 className="text-3xl font-bold text-center text-white mb-6 drop-shadow-lg">
            Login
          </h2>

          <p className="text-xs text-gray-200 text-center mb-4">
            Select your login type and enter credentials.
          </p>

          {/* Login Type dropdown */}
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-100 mb-1">
              Login Type
            </label>
            <select
              value={loginType}
              onChange={(e) => setLoginType(e.target.value)}
              className="w-full px-3 py-2 rounded-lg border border-gray-300 bg-white/70 focus:ring-indigo-500 focus:border-indigo-500"
            >
              <option value="user">User</option>
              <option value="admin">Admin</option>
            </select>
          </div>

          {/* Username */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-100 mb-1">Username</label>
              <input
                type="text"
                required
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg bg-white/70 focus:bg-white focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>

            {/* Password */}
            <div>
              <label className="block text-sm font-medium text-gray-100 mb-1">Password</label>
              <input
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg bg-white/70 focus:bg-white focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>

            <button
              type="submit"
              className="w-full mt-6 px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition duration-200"
            >
              Login
            </button>
          </form>

          {/* Error message */}
          {message && message.type === 'error' && (
            <div className="p-3 mt-4 rounded-lg text-sm bg-red-100 text-red-700 text-center">
              {message.text}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Login;
